package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.economy.EconomyEngine.*;
import static io.github.jesterportfolio.hearth.economy.EconomyContent.*;

class EconomyFlowTest {
    private final UUID realm=UUID.randomUUID();
    private Properties settings(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/economy-demo.properties")),java.nio.charset.StandardCharsets.UTF_8)){var p=new Properties();p.load(r);return p;}catch(Exception e){throw new AssertionError(e);}}
    private final Properties p=settings();private final EconomyContent c=EconomyContent.parse(p);
    private final Key ingot=new Key("capital","iron_ingot"),ore=new Key("capital","iron_ore"),mine=new Key("mine","iron_ore");
    @Test void actualProductionConsumptionAndInputsAreSeparated(){var step=advance(realm,c,initial(c));var f=step.flows().get(ingot);assertEquals(3,f.produced());assertEquals(3,f.consumed());assertEquals(100,f.before());assertEquals(100,f.after());assertEquals(6,step.flows().get(ore).inputs());assertEquals(194,step.flows().get(ore).after());assertEquals(10,step.flows().get(mine).departed());assertEquals(0,step.flows().get(mine).produced());}
    @Test void delayedArrivalIsNotProduction(){var s=initial(c);Step step=null;for(int i=0;i<4;i++){step=advance(realm,c,s);s=step.state();}assertEquals(10,step.flows().get(ore).arrived());assertEquals(0,step.flows().get(ore).produced());assertEquals(10,step.flows().get(mine).produced());}
    @Test void unmetDemandAndRecipeShortageUseActualAmounts(){var rows=new HashMap<>(initial(c).markets());rows.put(ingot,new Market(0,300,0));rows.put(ore,new Market(2,100,0));var step=advance(realm,c,new State(0,rows,List.of(),List.of()));assertEquals(1,step.flows().get(ingot).produced());assertEquals(1,step.flows().get(ingot).consumed());assertEquals(2,step.flows().get(ingot).shortage());assertEquals(2,step.flows().get(ore).inputs());}
    @Test void contentEfficiencyAffectsActualOutputWithoutNewRule(){var changed=settings();changed.setProperty("facility.capital_smelter.efficiency","0");var content=EconomyContent.parse(changed);var step=advance(realm,content,initial(content));assertEquals(0,step.flows().get(ingot).produced());assertEquals(0,step.flows().get(ore).inputs());assertEquals(3,step.flows().get(ingot).consumed());}
    @Test void eventsBlockOnlyNewDepartureAndExpireNormally(){var s=new State(0,initial(c).markets(),List.of(new Shipment(UUID.randomUUID(),"ore_road","mine","capital","iron_ore",7,1)),List.of(new Active(UUID.randomUUID(),"road_block",1,2)));var blocked=advance(realm,c,s);assertEquals(7,blocked.flows().get(ore).arrived());assertEquals(0,blocked.flows().get(mine).departed());assertEquals(10,advance(realm,c,blocked.state()).flows().get(mine).departed());}
    @Test void firstSurgeTickOutputIsTargetLimitedRatherThanCapacity(){var step=advance(realm,c,new State(0,initial(c).markets(),List.of(),List.of(new Active(UUID.randomUUID(),"demand_surge",1,13))));assertEquals(3,step.flows().get(ingot).produced());assertEquals(6,step.flows().get(ingot).consumed());assertEquals(97,step.flows().get(ingot).after());}
    @Test void everyCellConservesStockAndMapIsImmutable(){var s=initial(c);for(int i=0;i<20;i++){var step=advance(realm,c,s);for(var e:step.flows().entrySet()){var f=e.getValue();assertEquals(f.after(),f.before()+f.produced()+f.arrived()-f.inputs()-f.consumed()-f.departed());assertEquals(step.state().markets().get(e.getKey()).stock(),f.after());assertEquals(step.state().tick(),f.tick());}s=step.state();}var finalStep=advance(realm,c,s);assertThrows(UnsupportedOperationException.class,()->finalStep.flows().clear());}
    @Test void invalidAndUnbalancedMeasurementsAreRejected(){assertThrows(IllegalArgumentException.class,()->new Flow(0,10,0,0,0,0,0,0,10));assertThrows(IllegalArgumentException.class,()->new Flow(1,10,0,0,0,0,0,0,9));assertThrows(IllegalArgumentException.class,()->new Flow(1,10,-1,0,0,0,0,0,9));}
    @Test void publicProjectionOnlyIncludesConfiguredGoods(){var step=advance(realm,c,initial(c));var publicSettings=settings();publicSettings.setProperty("report-goods","iron_ingot");publicSettings.setProperty("report-routes","");publicSettings.setProperty("report-facilities","");var d=EconomyReport.parse(publicSettings,c,EconomyShop.parse(p,c));var view=d.project(c,step.state(),"capital",step.flows());assertEquals(1,view.markets().size());assertEquals(step.flows().get(ingot),view.markets().getFirst().flow());assertFalse(view.toString().contains("iron_ore"));}
    @Test void legacyMissingMeasurementsAreNotInventedAndStaleIsRejected(){var d=EconomyReport.parse(p,c,EconomyShop.parse(p,c));assertNull(d.project(c,initial(c),"capital").markets().getFirst().flow());var step=advance(realm,c,initial(c));assertThrows(IllegalArgumentException.class,()->d.project(c,initial(c),"capital",step.flows()));var partial=new HashMap<>(step.flows());partial.remove(mine);assertThrows(IllegalArgumentException.class,()->d.project(c,step.state(),"capital",partial));}
    @Test void facilityDiagnosisDistinguishesTargetsInputsAndDisabledCapacity(){var d=EconomyReport.parse(p,c,EconomyShop.parse(p,c));var rows=new HashMap<>(initial(c).markets());rows.put(ingot,new Market(0,300,0));rows.put(ore,new Market(2,100,0));var poor=d.project(c,new State(0,rows,List.of(),List.of()),"capital").facilities().getFirst();assertEquals(5,poor.capacity());assertEquals(1,poor.possible());assertEquals("입력 재료 부족",poor.restriction());rows.put(ingot,new Market(103,300,0));assertEquals("목표 재고 충족",d.project(c,new State(0,rows,List.of(),List.of()),"capital").facilities().getFirst().restriction());var stopped=new State(1,rows,List.of(),List.of(new Active(UUID.randomUUID(),"mine_collapse",1,25)));assertEquals(0,d.project(c,stopped,"mine").facilities().getFirst().possible());}
}
